import { test, expect } from '@playwright/test';

test.describe('File Upload with Title and Description', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload');
  });

  test('should allow user to upload a file and set title and description', async ({ page }) => {
    await page.setInputFiles(getByLabel('File Upload'), 'path/to/file.txt');
    await page.fill(getByLabel('Title'), 'Test File Title');
    await page.fill(getByLabel('Description'), 'This is a test description for the uploaded file.');
    await page.click(getByRole('button', { name: 'Submit' }));

    const successMessage = await page.getByText('File uploaded successfully!');
    await expect(successMessage).toBeVisible();
  });

  test('should display error when title is missing', async ({ page }) => {
    await page.setInputFiles(getByLabel('File Upload'), 'path/to/file.txt');
    await page.fill(getByLabel('Description'), 'This is a test description for the uploaded file.');
    await page.click(getByRole('button', { name: 'Submit' }));

    const errorMessage = await page.getByText('Title is required');
    await expect(errorMessage).toBeVisible();
  });
});
